import { exactSpan } from "./contracts.js";
import { condition } from "./compile-conditions.js";
import { CompileError, type CompileLeaf } from "./compile-fragments.js";
import { historyConnective } from "./compile-connective-history.js";
import { AMONG_TARGETS } from "./families/vocabulary.js";

/**
 * Where a set-up may (or may not) place a unit. Three folds tie placement wording to the set-up
 * it qualifies instead of letting it gate that set-up:
 *
 * - Add-unit then set-up: "add a new unit … and set it up" is one add-unit that is set up on the
 *   battlefield. The set-up leaf, whose "it" is the new unit, merges into the add-unit.
 * - Set-up restriction: "enemy units that are set up from Reserves cannot be set up within 12\" of
 *   this model". The set-up moment right before a forbidden set-up (allow false) is not a trigger:
 *   it names whose set-ups are forbidden ({owner}) and where they come from (its `from`).
 * - Placement limits: a distance, a region or "not engaged" right after a set-up or a merged
 *   add-unit, joined only by glue words ("that is", "and", ","), is where that unit is set up.
 *
 * `foldSetUpPlacement` runs before antecedents bind, because "it" and "that unit" here name the
 * set-up's own unit, not the unit an earlier leaf introduced. It marks each limit with its owner.
 * `foldSetUpLimits` runs after unit-filters fold (a limit can measure to the filter after it) and
 * lowers each marked limit into its owner's placement fields.
 */

type Node = Record<string, unknown>;

/** Wording between a set-up and its limits, or between two limits, that adds no meaning. */
const LIMIT_GLUE = /^(?:\s|,|\band\b|\bthat (?:is|are)\b|\banywhere(?: on the battlefield)?)*$/iu;
/** Wording between an add-unit and the set-up of its new unit ("… and set it up"). */
const ADD_UNIT_GLUE = /^[\s,]*(?:\band\b)?[\s,]*$/iu;
const SENTENCE_BREAK = /[.;:]/u;

/** set-up parameters a merged add-unit can carry over; any other has no add-unit form. */
const MERGEABLE_SET_UP_KEYS = new Set(["subject", "to", "placement"]);

/** Owner key: the owner's start byte, which no other leaf of the ability shares. */
const LIMIT_OWNER = "set_up_limit_owner";

/** Wording between an add-unit and the permission set-up after it: "… . If you do, that <unit> can be set up". */
const PERMISSION_LEAD = /^\s*\.\s*If you do,\s*$/iu;
/** The add-unit parameter that marks a permission to set up the new unit within a range of the destroyed unit. */
const PERMISSION_FLAG = "set_up_permission";
/** The limit parameter that marks a limit of a permission: it lowers to allow_engagement_with, not a near or away_from entry. */
const PERMISSION_LIMIT = "set_up_permission_limit";

const sameFragment = (left: CompileLeaf, right: CompileLeaf) => (left.fragment ?? null) === (right.fragment ?? null);

/** The source wording between two leaves, or null when it cannot be read. */
function gap(previous: CompileLeaf, next: CompileLeaf, sourceText: string | undefined): string | null {
  if (sourceText === undefined || previous.end_byte === undefined || next.start_byte < previous.end_byte) return null;
  return exactSpan(sourceText, previous.end_byte, next.start_byte);
}

/** A leaf that can say where a set-up places its unit. */
function isLimit(leaf: CompileLeaf): boolean {
  if (leaf.role !== "CONDITION") return false;
  const p = leaf.parameters;
  if (leaf.family_id === "unit-position") return (p.kind === "within" || p.kind === "beyond") && p.of !== undefined;
  if (leaf.family_id === "in-region") return true;
  if (leaf.family_id === "unit-state") {
    const states = p.states as unknown[] | undefined;
    return Array.isArray(states) && states.length === 1 && states[0] === "engaged" && p.negated === true && p.with === undefined && p.at === undefined;
  }
  return false;
}

const isSetUp = (leaf: CompileLeaf) => leaf.role === "EFFECT" && leaf.family_id === "set-up";
const isAddUnit = (leaf: CompileLeaf) => leaf.role === "EFFECT" && leaf.family_id === "add-unit";

/** Check one limit's own parameters; what the DSL placement cannot say is refused here. */
function checkLimit(limit: CompileLeaf, ownerSubject: unknown): void {
  const p = limit.parameters;
  if (p.subject !== undefined && p.subject !== "antecedent" && p.subject !== ownerSubject) {
    throw new CompileError(`A placement limit after a set-up places the set-up's unit; this ${limit.family_id} is said of ${JSON.stringify(p.subject)}.`);
  }
  if (limit.family_id === "in-region") {
    if (p.negated === true) throw new CompileError("A set-up placed outside a region has no DSL placement; only within a region.");
    if (p.models !== undefined) throw new CompileError("A set-up's region placement places the whole unit; in-region models has no placement form.");
  }
  if (limit.family_id === "unit-position") {
    if (p.of === "antecedent") throw new CompileError("A set-up's placement limit measures to an earlier unit; name the place (event-subject, marker, this-model) instead of antecedent.");
    if (p.of_other === true) throw new CompileError("A set-up's placement limit measured to another unit than the one set up has no DSL placement yet.");
    const away = (p.kind === "beyond") !== (p.negated === true);
    if (away && p.wholly === true) throw new CompileError("A set-up cannot be placed wholly more than a distance away; wholly qualifies only within.");
  }
}

/**
 * Fold add-unit set-ups and set-up restrictions, and mark the placement limits after a set-up
 * with the set-up (or add-unit) they place. Without source text, nothing is folded.
 */
export function foldSetUpPlacement(leaves: readonly CompileLeaf[], sourceText: string | undefined): readonly CompileLeaf[] {
  if (sourceText === undefined || !leaves.some((leaf) => isSetUp(leaf))) return leaves;
  const result = [...leaves];
  const drop = new Set<number>();
  // The add-unit whose run (its own set-up and placement limits) ends at `end`, for a permission set-up after it.
  let addUnit: { at: number; end: number } | null = null;
  for (let at = 0; at < result.length; at++) {
    const leaf = result[at]!;
    let last = at;
    let ownerAt = at;
    let permission = false;
    if (isAddUnit(leaf)) {
      const next = result[at + 1];
      const between = next ? gap(leaf, next, sourceText) : null;
      if (!next || !isSetUp(next) || next.parameters.subject !== "antecedent" || !sameFragment(leaf, next) || between === null || !ADD_UNIT_GLUE.test(between)) {
        addUnit = { at, end: at };
        continue;
      }
      if (leaf.parameters.held_in !== undefined) throw new CompileError("A unit added in Strategic Reserves is not also set up on the battlefield; drop held_in or the set-up.");
      const extra = Object.keys(next.parameters).find((key) => !MERGEABLE_SET_UP_KEYS.has(key));
      if (extra) throw new CompileError(`The set-up of a newly added unit has no add-unit form for ${extra}.`);
      if (next.parameters.to !== "battlefield") throw new CompileError("The set-up of a newly added unit puts it on the battlefield; a unit added in Reserves is add-unit held_in.");
      const merged: Node = { ...leaf.parameters, set_up: true };
      if (next.parameters.placement !== undefined) merged.set_up_placement = next.parameters.placement;
      result[at] = { ...leaf, parameters: merged, end_byte: next.end_byte };
      drop.add(at + 1);
      last = at + 1;
    } else if (isSetUp(leaf) && leaf.parameters.allow !== false && permissionLead(result, at, sourceText) !== null) {
      // "… and set it up. If you do, that unit can be set up within Engagement Range of …": a permission of the add-unit.
      const lead = permissionLead(result, at, sourceText)!;
      if (addUnit === null || addUnit.end !== lead.anchorAt) throw new CompileError("A permission to set up a unit must follow the add-unit it permits, in the same sentence.");
      if (leaf.parameters.subject !== "antecedent" || leaf.parameters.to !== "battlefield") throw new CompileError("A permission to set up a newly added unit names it as antecedent and sets it up on the battlefield.");
      if (leaf.parameters.placement !== undefined) throw new CompileError("A set-up permission with its own placement has no add-unit form; a permission may only lower a range limit.");
      const extra = Object.keys(leaf.parameters).find((key) => key !== "subject" && key !== "to");
      if (extra) throw new CompileError(`A set-up permission has no add-unit form for ${extra}.`);
      const added = result[addUnit.at]!;
      if (added.parameters[PERMISSION_FLAG] === true) throw new CompileError("A newly added unit has one set-up permission; this sentence grants a second.");
      result[addUnit.at] = { ...added, parameters: { ...added.parameters, [PERMISSION_FLAG]: true } };
      drop.add(at);
      if (lead.filterAt !== null) drop.add(lead.filterAt);
      ownerAt = addUnit.at;
      last = at;
      permission = true;
    } else if (isSetUp(leaf) && leaf.parameters.allow === false && leaf.parameters.subject === "antecedent") {
      const moment = result[at - 1];
      const between = moment ? gap(moment, leaf, sourceText) : null;
      if (moment && moment.role === "EVENT" && moment.family_id === "event" && moment.parameters.kind === "set-up" && sameFragment(moment, leaf) && between !== null && !SENTENCE_BREAK.test(between)) {
        result[at] = restriction(result, at, moment, sourceText);
        drop.add(at - 1);
      }
    } else if (isSetUp(leaf) && leaf.parameters.allow !== false && leaf.parameters.subject === "antecedent" && scopingMoment(result, at, sourceText)) {
      const momentAt = scopingMomentAt(result, at);
      result[at] = scopedPermission(result[momentAt]!, leaf);
      drop.add(momentAt);
    } else if (!isSetUp(leaf)) {
      continue;
    }
    const ownerLeaf = result[ownerAt]!;
    const ownerSubject = isSetUp(ownerLeaf) && ownerLeaf.parameters.restricted_owner === undefined ? ownerLeaf.parameters.subject : "antecedent";
    let limits = 0;
    for (let next = last + 1; next < result.length; next++) {
      const candidate = result[next]!;
      // "Remove your <unit-filter among> unit from the battlefield and then set it back up …": the owner's own span holds the
      // among-filter that names its unit (bindTargetRefs binds it), so the run starts after that wording.
      if (containedAmong(ownerLeaf, candidate)) continue;
      const between = gap(containedAmong(ownerLeaf, result[next - 1]!) ? ownerLeaf : result[next - 1]!, candidate, sourceText);
      if (stepsOverAmong(candidate, result[next + 1], ownerLeaf, between, sourceText)) continue;
      if (!isLimit(candidate) || !sameFragment(ownerLeaf, candidate) || between === null || !LIMIT_GLUE.test(between)) break;
      checkLimit(candidate, ownerSubject);
      result[next] = { ...candidate, parameters: { ...candidate.parameters, ...(candidate.parameters.subject !== undefined ? { subject: "this-unit" } : {}), [LIMIT_OWNER]: ownerLeaf.start_byte, ...(permission ? { [PERMISSION_LIMIT]: true } : {}) } };
      limits += 1;
      last = next;
    }
    if (permission && limits === 0) {
      throw new CompileError("A permission to set up a newly added unit names no range; the permission has no DSL form without Engagement Range.");
    }
    addUnit = isAddUnit(ownerLeaf) ? { at: ownerAt, end: last } : null;
    if (ownerLeaf.parameters.allow === false && limits > 1) {
      throw new CompileError("A forbidden set-up with more than one placement limit leaves unclear which zone is barred; split it into one restriction per zone.");
    }
    if (ownerLeaf.parameters.restricted_owner !== undefined) {
      if (limits === 0) throw new CompileError("A set-up restriction names no zone: a placement limit must follow \"cannot be set up\".");
      // "Enemy units that are set up from Reserves cannot be set up …, and …": the moment opens a second effect.
      const after = result[last + 1];
      const tail = after ? gap(result[last]!, after, sourceText) : null;
      if (after && after.role === "EFFECT" && sameFragment(ownerLeaf, after) && tail !== null && !SENTENCE_BREAK.test(tail)) {
        throw new CompileError("A set-up moment that a restriction consumes cannot also open another effect in its sentence.");
      }
    }
    at = last;
  }
  return result.filter((_, index) => !drop.has(index));
}

/**
 * A set-up that follows "If you do," (optionally after the unit-filter that names its unit): the
 * permission wording. Null when the wording before the set-up is anything else.
 */
function permissionLead(result: readonly CompileLeaf[], at: number, sourceText: string | undefined): { anchorAt: number; filterAt: number | null } | null {
  const set = result[at]!;
  if (sourceText === undefined || set.parameters.subject !== "antecedent") return null;
  const prior = result[at - 1];
  const filterAt = prior !== undefined && prior.family_id === "unit-filter" && sameFragment(prior, set) ? at - 1 : null;
  const anchorAt = filterAt === null ? at - 1 : at - 2;
  const anchor = result[anchorAt];
  if (anchor === undefined || !sameFragment(anchor, set)) return null;
  const lead = gap(anchor, filterAt === null ? set : result[filterAt]!, sourceText);
  if (lead === null || !PERMISSION_LEAD.test(lead)) return null;
  if (filterAt !== null && gap(result[filterAt]!, set, sourceText)?.trim() !== "") return null;
  return { anchorAt, filterAt };
}

/** An among-filter that lies inside the span of the set-up (or add-unit) that its reference names the unit of. */
function containedAmong(owner: CompileLeaf, leaf: CompileLeaf): boolean {
  return leaf !== owner && leaf.family_id === "unit-filter" && leaf.parameters.among === AMONG_TARGETS && sameFragment(owner, leaf)
    && owner.end_byte !== undefined && leaf.end_byte !== undefined && leaf.start_byte >= owner.start_byte && leaf.end_byte <= owner.end_byte;
}

/**
 * An among-filter between two placement limits ("… within 6″ of your MONOLITH model and not within …"):
 * the run steps over it, and bindTargetRefs binds it to the limit before it.
 */
function stepsOverAmong(candidate: CompileLeaf, after: CompileLeaf | undefined, owner: CompileLeaf, between: string | null, sourceText: string | undefined): boolean {
  if (candidate.family_id !== "unit-filter" || candidate.parameters.among !== AMONG_TARGETS || !sameFragment(owner, candidate)) return false;
  if (between === null || !LIMIT_GLUE.test(between) || after === undefined || !isLimit(after) || !sameFragment(owner, after)) return false;
  const tail = gap(candidate, after, sourceText);
  return tail !== null && LIMIT_GLUE.test(tail);
}

/** A forbidden set-up whose units are named by the set-up moment before it. */
function restriction(list: readonly CompileLeaf[], at: number, moment: CompileLeaf, sourceText: string): CompileLeaf {
  const setUp = list[at]!;
  const owner = moment.parameters.owner;
  if (moment.parameters.subject !== undefined) throw new CompileError("A set-up moment with a subject names one unit, not a side; a set-up restriction needs owner.");
  if (owner === undefined) throw new CompileError("A set-up restriction forbids the set-ups of one side's units; its set-up moment names no owner.");
  const from = moment.parameters.from;
  if (from === undefined) throw new CompileError("A set-up restriction's moment says where the units are set up from (from Reserves); without it, it would also forbid deployment.");
  if (setUp.parameters.from !== undefined && setUp.parameters.from !== from) throw new CompileError(`A set-up restriction's moment is from ${String(from)}, but its set-up says from ${JSON.stringify(setUp.parameters.from)}.`);
  const before = list[at - 2];
  const lead = before ? gap(before, moment, sourceText) : null;
  if (before && before.family_id === "unit-filter" && sameFragment(before, moment) && lead !== null && !SENTENCE_BREAK.test(lead)) {
    throw new CompileError("A unit-filter on a set-up restriction's moment has no fold yet; the restriction would forbid every unit of that side.");
  }
  return { ...setUp, start_byte: moment.start_byte, parameters: { ...setUp.parameters, subject: "this-unit", from, restricted_owner: owner } };
}

/**
 * "Until the end of the phase, when setting up your unit on the battlefield from Reserves, it can be
 * set up anywhere …", "… when your unit is set up using the Deep Strike ability, it can be set up
 * …": inside the window a permission lasts for, a set-up moment right before a permitted set-up of
 * its own unit, joined by a comma, names which set-ups the permission covers. It is not a trigger:
 * its source (from) or the Deep Strike rules it uses (via) belong to the set-up.
 */
/**
 * Before folds: whether the set-up moment at `at`, after a reviewed "If", scopes the permitted set-up
 * of its own unit after it (past an arrival window and the by-ability it used), which
 * `foldSetUpPlacement` folds it into. Its "If" then plans no history condition.
 */
export function scopesSetUpPermission(list: readonly CompileLeaf[], at: number, sourceText: string | undefined): boolean {
  const moment = list[at]!;
  if (sourceText === undefined || moment.family_id !== "event" || moment.parameters.kind !== "set-up") return false;
  let next = at + 1;
  if (list[next]?.family_id === "reserves-arrival" && sameFragment(list[next]!, moment)) next += 1;
  const byAbility = list[next]?.family_id === "by-ability" && sameFragment(list[next]!, moment) ? list[next++]! : undefined;
  const setUp = list[next];
  if (!setUp || !isSetUp(setUp) || setUp.parameters.allow === false || setUp.parameters.subject !== "antecedent" || !sameFragment(setUp, moment)) return false;
  if (moment.parameters.from === undefined && byAbility?.parameters.id !== "deep-strike") return false;
  const between = gap(list[next - 1]!, setUp, sourceText);
  return between !== null && /^\s*(?:ability\s*)?,\s*$/iu.test(between);
}

/** The set-up moment a permission at `at` is scoped by, past an arrival window between them, or -1. */
function scopingMomentAt(result: readonly CompileLeaf[], at: number): number {
  return result[at - 1]?.family_id === "reserves-arrival" ? at - 2 : at - 1;
}

function scopingMoment(result: readonly CompileLeaf[], at: number, sourceText: string): boolean {
  const momentAt = scopingMomentAt(result, at);
  const moment = result[momentAt];
  const leaf = result[at]!;
  const last = result[at - 1]!;
  if (!moment || moment.role !== "EVENT" || moment.family_id !== "event" || moment.parameters.kind !== "set-up" || !sameFragment(moment, leaf)) return false;
  // Only inside a window the permission lasts for ("Until the end of the phase, when …"), or after a
  // reviewed "If" ("If it arrives back … using the Deep Strike ability, it can be set up …"); a bare
  // "When this unit is set up, it can be set up …" stays a reactive trigger.
  if (historyConnective(moment) === undefined) {
    const window = result[momentAt - 1];
    if (!window || window.role !== "DURATION" || !sameFragment(window, moment)) return false;
    const lead = gap(window, moment, sourceText);
    if (lead === null || !/^\s*,\s*$/u.test(lead)) return false;
  }
  if (last !== moment && !sameFragment(last, leaf)) return false;
  const between = gap(last, leaf, sourceText);
  // A folded by-ability ("using the Deep Strike ability") keeps its own words between the moment and the set-up.
  const joined = moment.parameters.by_ability !== undefined ? /^\s*(?:using [^,.;:]*\bability\s*)?,\s*$/iu : /^\s*,\s*$/u;
  if (between === null || !joined.test(between)) return false;
  return moment.parameters.from !== undefined || moment.parameters.by_ability === "deep-strike";
}

function scopedPermission(moment: CompileLeaf, setUp: CompileLeaf): CompileLeaf {
  const p = moment.parameters;
  const extra = Object.keys(p).find((key) => !["kind", "from", "by_ability", "owner", "subject"].includes(key));
  if (p.subject !== undefined && p.subject !== "antecedent" && p.subject !== "this-unit") throw new CompileError("A set-up moment that scopes a permission names the permission's own unit.");
  if (extra !== undefined) throw new CompileError(`A set-up moment that scopes a set-up permission has no DSL form for ${extra}.`);
  if (p.owner !== undefined && p.owner !== "friendly") throw new CompileError("A set-up moment that scopes a permission for your unit names a friendly unit.");
  if (p.from !== undefined && setUp.parameters.from !== undefined && setUp.parameters.from !== p.from) {
    throw new CompileError(`A set-up permission's moment is from ${String(p.from)}, but its set-up says from ${JSON.stringify(setUp.parameters.from)}.`);
  }
  if (p.by_ability === "deep-strike" && setUp.parameters.via !== undefined) throw new CompileError("A set-up permission scoped to Deep Strike already names how it is set up.");
  // The moment's "If" is the scoping itself, so it does not carry over to the set-up.
  return {
    ...setUp, start_byte: moment.start_byte, connectives: setUp.connectives,
    parameters: { ...setUp.parameters, ...(p.from !== undefined ? { from: p.from } : {}), ...(p.by_ability === "deep-strike" ? { via: "deep-strike" } : {}) },
  };
}

/** A forbidden set-up ("enemy units cannot be set up within 12\" of …") holds until it ends, like a permission. */
export function isForbiddenSetUp(node: Node): boolean {
  return node.type === "set-up" && (node.modifier as Node | undefined)?.allow === false;
}

/** Lower every marked placement limit into its owner and drop it. */
export function foldSetUpLimits(leaves: readonly CompileLeaf[]): readonly CompileLeaf[] {
  if (!leaves.some((leaf) => leaf.parameters[LIMIT_OWNER] !== undefined)) return leaves;
  const result = [...leaves];
  const drop = new Set<number>();
  result.forEach((leaf, index) => {
    const key = leaf.parameters[LIMIT_OWNER];
    if (key === undefined) return;
    const ownerAt = result.findIndex((other) => other.role === "EFFECT" && (isSetUp(other) || isAddUnit(other)) && other.start_byte === key);
    if (ownerAt === -1) throw new CompileError(`A placement limit (${leaf.family_id}) lost the set-up it places.`);
    result[ownerAt] = { ...result[ownerAt]!, parameters: withLimit(result[ownerAt]!, leaf) };
    drop.add(index);
  });
  return result.filter((_, index) => !drop.has(index));
}

function withLimit(owner: CompileLeaf, limit: CompileLeaf): Node {
  const parameters: Node = { ...owner.parameters };
  const { [LIMIT_OWNER]: _owner, [PERMISSION_LIMIT]: _permission, ...rest } = limit.parameters;
  const append = (field: string, item: Node) => { parameters[field] = [...((parameters[field] as Node[] | undefined) ?? []), item]; };
  if (limit.parameters[PERMISSION_LIMIT] === true) return permissionLimit(parameters, limit);
  if (limit.family_id === "unit-state") {
    parameters.folded_unengaged = true;
    return parameters;
  }
  let node = condition({ ...limit, parameters: { ...rest, ...(rest.subject !== undefined ? { subject: "this-unit" } : {}) } });
  let negated = false;
  while (node.operator === "not") {
    negated = !negated;
    node = (node.operands as Node[])[0]!;
  }
  const lowered = (node.parameters ?? {}) as Node;
  const { subject: _subject, ...found } = node.type === "matches" ? (((lowered.filter as Node).within ?? {}) as Node) : lowered;
  if (limit.family_id === "in-region") {
    if (parameters.folded_in_region !== undefined) throw new CompileError("A set-up is placed within two regions; the DSL placement holds one.");
    parameters.folded_in_region = { region: found.region, ...(found.wholly === true ? { wholly: true } : {}) };
    return parameters;
  }
  if (limit.parameters.weapon_range !== undefined) throw new CompileError("A half- or full-weapon distance has no placement form.");
  if (node.type !== "within" && (node.type !== "matches" || (lowered.filter as Node).within === undefined)) throw new CompileError(`A ${limit.family_id} placement limit lowered to ${String(node.type)}, which has no placement form.`);
  if (!negated) {
    append("folded_near", { of: found.of, range: found.range, ...(found.wholly === true ? { wholly: true } : {}) });
    return parameters;
  }
  const of = found.of as Node | string;
  const anyEnemy = typeof of === "object" && Object.keys(of).length === 1 && of.owner === "enemy";
  // "More than 9\" away from all enemy units" on a permitted set-up is its min_enemy_distance.
  // A range that is a string ("engagement") is not a fixed inch count, so it takes the away-from path below.
  if (anyEnemy && isSetUp(owner) && owner.parameters.allow !== false && typeof found.range === "object" && found.range !== null) {
    // min_enemy_distance is a fixed inch count; a named range (aura_of) has no such field.
    if ("aura_of" in (found.range as Node)) throw new CompileError("A set-up's minimum distance from enemy units is a fixed inch count; a named range has no placement shape yet.");
    const inches = (found.range as Node).inches;
    if (parameters.min_enemy_distance !== undefined && parameters.min_enemy_distance !== inches) {
      throw new CompileError(`A set-up already sets up more than ${String(parameters.min_enemy_distance)}" from enemy units; its placement limit says ${String(inches)}".`);
    }
    parameters.min_enemy_distance = inches;
    return parameters;
  }
  append("folded_away_from", { of, range: found.range });
  return parameters;
}

/**
 * A permission's only limit: within Engagement Range of the destroyed unit (of event-object), which
 * the DSL carries as the add-unit's allow_engagement_with. Any other limit has no permission form.
 */
function permissionLimit(parameters: Node, limit: CompileLeaf): Node {
  const p = limit.parameters;
  const engagementOfDestroyed = limit.family_id === "unit-position" && p.kind === "within" && p.range_ref === "engagement" && p.of === "event-object"
    && p.negated !== true && p.wholly !== true && p.inches === undefined;
  if (!engagementOfDestroyed) throw new CompileError("A permission to set up within a range has no DSL form beyond Engagement Range of the destroyed unit.");
  return { ...parameters, folded_allow_engagement_with: "event-object" };
}

/** A placement limit folded by foldSetUpPlacement and not yet lowered into its owner. */
export function isPlacedLimit(leaf: CompileLeaf): boolean {
  return leaf.parameters[LIMIT_OWNER] !== undefined;
}
